{"implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    fixed_point = False
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old, new = p['old'], p['new']
            new_text = text.replace(old, new)
            if new_text != text:
                applications.append(p['name'])
                text = new_text
                changed = True
        if not changed:
            fixed_point = True
            break
    return {'applications': applications, 'fixed_point': fixed_point, 'text': text}
"}
